assertion:
param($Connections)
$configs = Get-DkimSigningConfig
$disabled = $configs | Where-Object { $_.Enabled -eq $false }
if ($disabled.Count -gt 0) {
  return @{ Pass = $false; Detail = "DKIM disabled on $($disabled.Count) domain(s): $($disabled.Domain -join ', ')"; Evidence = ($configs | Select-Object Domain, Enabled, Status) }
}
return @{ Pass = $true; Detail = 'DKIM is enabled on all accepted domains.'; Evidence = ($configs | Select-Object Domain, Enabled, Status) }

param($Connections)
$domains = Get-AcceptedDomain | Where-Object { $_.DomainType -eq 'Authoritative' }
$results = foreach ($d in $domains) {
  $dns = Resolve-DnsName -Name $d.DomainName -Type TXT -ErrorAction SilentlyContinue
  $spf = $dns | Where-Object { $_.Strings -like '*v=spf1*' }
  [PSCustomObject]@{ Domain = $d.DomainName; HasSPF = ($null -ne $spf); SPFRecord = ($spf.Strings -join ' ') }
}
$missing = $results | Where-Object { -not $_.HasSPF }
if ($missing.Count -gt 0) {
  return @{ Pass = $false; Detail = "SPF missing on $($missing.Count) domain(s): $($missing.Domain -join ', ')"; Evidence = $results }
}
return @{ Pass = $true; Detail = 'SPF records found on all authoritative domains.'; Evidence = $results }

param($Connections)
$domains = Get-AcceptedDomain | Where-Object { $_.DomainType -eq 'Authoritative' }
$results = foreach ($d in $domains) {
  $dns = Resolve-DnsName -Name "_dmarc.$($d.DomainName)" -Type TXT -ErrorAction SilentlyContinue
  $dmarc = $dns | Where-Object { $_.Strings -like '*v=DMARC1*' }
  $policy = if ($dmarc) { if ($dmarc.Strings -match 'p=(quarantine|reject)') { $matches[1] } else { 'none' } } else { 'missing' }
  [PSCustomObject]@{ Domain = $d.DomainName; Policy = $policy; Record = ($dmarc.Strings -join ' ') }
}
$weak = $results | Where-Object { $_.Policy -notin @('quarantine','reject') }
if ($weak.Count -gt 0) {
  return @{ Pass = $false; Detail = "$($weak.Count) domain(s) missing DMARC or using 'none' policy: $($weak.Domain -join ', ')"; Evidence = $results }
}
return @{ Pass = $true; Detail = 'All domains have DMARC with quarantine or reject policy.'; Evidence = $results }

param($Connections)
$policy = Get-MalwareFilterPolicy -Identity Default
if (-not $policy.EnableFileFilter) {
  return @{ Pass = $false; Detail = 'Common Attachment Types Filter is DISABLED on the Default malware policy.'; Evidence = ($policy | Select-Object Identity, EnableFileFilter, FileTypes) }
}
return @{ Pass = $true; Detail = 'Common Attachment Types Filter is enabled.'; Evidence = ($policy | Select-Object Identity, EnableFileFilter, FileTypes) }
